cd examples && python -c "
import json
# codex + hermes need full lines (first lines are long)
for f in ['example_codex_session.jsonl','example_hermes_session.jsonl']:
    print('===',f)
    with open(f,encoding='utf-8') as h:
        for i,line in enumerate(h):
            if i>8: break
            try: e=json.loads(line)
            except Exception: continue
            def shape(o,d=0):
                if isinstance(o,dict): return {k:(shape(v,d+1) if d<2 else type(v).__name__) for k,v in o.items()}
                if isinstance(o,list): return [shape(o[0],d+1)] if o else []
                return str(o)[:50]
            print(json.dumps(shape(e))[:600])
"
